/* ---------------- reveal-on-scroll ---------------- */
const io = new IntersectionObserver(es => es.forEach(e => { if (e.isIntersecting) e.target.classList.add('in'); }), { threshold: .15 });
document.querySelectorAll('.reveal').forEach(el => io.observe(el));

/* ---------------- lightning: real jagged bolt strikes + ambient flash ---------------- */
const flash = document.getElementById('flash');
const boltMain = document.getElementById('boltMain');
const boltFork = document.getElementById('boltFork');
const boltMain2 = document.getElementById('boltMain2');
const boltFork2 = document.getElementById('boltFork2');
function jaggedPath(x0, y0, x1, y1, segs, jitter) {
  const pts = [[x0, y0]];
  for (let i = 1; i <= segs; i++) {
    const t = i / segs;
    pts.push([x0 + (x1 - x0) * t + (Math.random() - .5) * jitter, y0 + (y1 - y0) * t]);
  }
  return pts;
}
function fireBolt(mainEl, forkEl) {
  const x0 = 80 + Math.random() * 840, x1 = x0 + (Math.random() - .5) * 300;
  const y1 = 240 + Math.random() * 300;
  const pts = jaggedPath(x0, -10, x1, y1, 9, 60);
  mainEl.setAttribute('d', 'M ' + pts.map(p => p[0].toFixed(1) + ' ' + p[1].toFixed(1)).join(' L '));
  let forkD = '';
  const forkCount = Math.random() < .8 ? (Math.random() < .35 ? 2 : 1) : 0;
  for (let f = 0; f < forkCount; f++) {
    const i = 2 + Math.floor(Math.random() * (pts.length - 4));
    const [fx, fy] = pts[i];
    const fang = Math.PI * .3 + Math.random() * Math.PI * .35;
    const flen = 40 + Math.random() * 100;
    const fx2 = fx + Math.cos(fang) * flen * (Math.random() < .5 ? -1 : 1), fy2 = fy + Math.sin(fang) * flen;
    forkD += `M ${fx.toFixed(1)} ${fy.toFixed(1)} L ${fx2.toFixed(1)} ${fy2.toFixed(1)} `;
  }
  forkEl.setAttribute('d', forkD);
  [mainEl, forkEl].forEach(el => { el.classList.remove('strike'); void el.offsetWidth; el.classList.add('strike'); });
}
function flashSky(intensity) {
  flash.style.transition = 'none'; flash.style.opacity = intensity;
  requestAnimationFrame(() => { flash.style.transition = 'opacity .55s ease-out'; flash.style.opacity = 0; });
}
function strikeLightning() {
  fireBolt(boltMain, boltFork);
  flashSky(.42 + Math.random() * .3);
  if (Math.random() < .5) { // real bolts often flicker/re-strike the same channel
    setTimeout(() => { fireBolt(boltMain, boltFork); flashSky(.3 + Math.random() * .2); }, 90 + Math.random() * 90);
  }
  if (Math.random() < .4) { // second, separate bolt elsewhere in the sky
    setTimeout(() => { fireBolt(boltMain2, boltFork2); flashSky(.2 + Math.random() * .15); }, 140 + Math.random() * 180);
  }
}
setInterval(() => { if (Math.random() < .5) strikeLightning(); }, 2400);

/* ---------------- ember/spark hero background (2D canvas, no 3D deps) ---------------- */
(function () {
  const canvas = document.getElementById('emberCanvas');
  const ctx = canvas.getContext('2d');
  let w, h, embers = [];
  function resize() {
    const hero = document.getElementById('hero');
    w = canvas.width = innerWidth * devicePixelRatio;
    h = canvas.height = hero.offsetHeight * devicePixelRatio;
    canvas.style.width = innerWidth + 'px'; canvas.style.height = hero.offsetHeight + 'px';
  }
  resize(); addEventListener('resize', resize);
  const N = 70;
  for (let i = 0; i < N; i++) embers.push({ x: Math.random() * w, y: Math.random() * h, r: (Math.random() * 1.8 + .4) * devicePixelRatio, s: Math.random() * .4 + .15, gold: Math.random() > .35 });
  function frame() {
    requestAnimationFrame(frame);
    ctx.clearRect(0, 0, w, h);
    for (const e of embers) {
      e.y -= e.s * devicePixelRatio; e.x += Math.sin(e.y * .01) * .3;
      if (e.y < -10) { e.y = h + 10; e.x = Math.random() * w; }
      ctx.beginPath(); ctx.arc(e.x, e.y, e.r, 0, 7);
      ctx.fillStyle = e.gold ? 'rgba(242,194,48,.55)' : 'rgba(200,16,46,.5)';
      ctx.fill();
    }
    const hero = document.getElementById('hero');
    const prog = Math.min(1, Math.max(0, -hero.getBoundingClientRect().top / (hero.offsetHeight * .9)));
    const ht = document.getElementById('heroText');
    if (ht) { ht.style.opacity = Math.max(0, 1 - prog * 1.7); ht.style.transform = `translateY(${prog * -40}px)`; }
  }
  frame();
})();

