/* ---- seasons (a season IS its robot: name, year, 3D file, specs...) ---- */
let seasons = [], canEdit = false, editingId = null, dbNS = null, assetsNS = null;
let fSpecsRows = [], fAchRows = [], fAlbumPhotos = [], fBannerAssetId = null;
const HOME_IDS = ['hero', 'homeStats'];

function esc(s) { return String(s || '').replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c])); }
function seasonExcerpt(s) { return (s.overview || '').slice(0, 90); }
/* unify legacy fields (robotImgUrl / album / heroUrl) with the new ordered "photos" array */
function seasonPhotos(s) {
  if (s.photos && s.photos.length) return s.photos;
  const legacy = (s.album && s.album.length) ? s.album.map(p => ({ ...p })) : (s.heroUrl ? [{ assetId: s.heroAssetId || null, url: s.heroUrl }] : []);
  if (s.robotImgUrl) legacy.push({ assetId: s.robotImgAssetId || null, url: s.robotImgUrl });
  return legacy;
}
function coverUrl(s) { const p = seasonPhotos(s); return p.length ? p[0].url : null; }
function thumbHTML(s) {
  const cov = coverUrl(s);
  if (cov) return `<img src="${esc(cov)}" alt="">`;
  return `<span class="ph">${esc((s.name || '?')[0])}</span>`;
}

const seasonGrid = document.getElementById('seasonGrid');
function renderSeasons() {
  document.getElementById('seasonsEmpty').hidden = seasons.length > 0 || canEdit;
  const cards = seasons.map((s, i) => `<button type="button" class="season-card reveal" data-id="${s.id}">
      <div class="season-thumb">${i === 0 ? '<span class="season-badge">Latest</span>' : ''}${thumbHTML(s)}</div>
      <div class="season-body"><span class="season-name">${esc(s.name)}</span><span class="season-year">${esc(s.year)}</span><span class="season-note">${esc(seasonExcerpt(s))}</span></div>
    </button>`).join('');
  const addCard = canEdit ? `<button type="button" class="robot-new" id="btnNewSeason"><span class="plus">+</span><span>New Season</span></button>` : '';
  seasonGrid.innerHTML = addCard + cards;
  seasonGrid.querySelectorAll('.season-card').forEach(c => { io.observe(c); c.addEventListener('click', () => { location.hash = 'season/' + c.dataset.id; }); });
  const nb = document.getElementById('btnNewSeason'); if (nb) nb.addEventListener('click', () => openForm(null));
  tryOpenPending();
}

