const PAGE_IDS = ['about', 'seasons', 'seasonPage', 'seasonLogsPage', 'resources', 'resourcePage', 'sponsors'];
function showPage(pageId) {
  HOME_IDS.forEach(id => document.getElementById(id).style.display = pageId ? 'none' : '');
  PAGE_IDS.forEach(id => document.getElementById(id).classList.toggle('show', id === pageId));
  if (pageId) window.scrollTo({ top: 0, behavior: 'instant' });
}
function showHome() { showPage(null); }
function showAboutPageEl() { showPage('about'); }
function showSeasonsListEl() { showPage('seasons'); }
function showSeasonPageEl() { showPage('seasonPage'); }
function showSeasonLogsPageEl() { showPage('seasonLogsPage'); }
function showResourcesListEl() { showPage('resources'); }
function showResourcePageEl() { showPage('resourcePage'); }
function showSponsorsEl() { showPage('sponsors'); if (window.startSponsors) startSponsors(); }
/* ---- sponsors: circular scroll carousel ----
   EDIT HERE: tier = 'diamond' | 'gold' | 'silver' | 'other'; logo = image URL or data: URI ('' shows the initial) */
var SPONSORS=[];   /* no built-in samples: sponsors are added on the page (Admin > Add sponsor) */
(function(){
  var THEME={diamond:['Diamond','#8fe3ff'],gold:['Gold','#f2c230'],silver:['Silver','#cfd5dc'],other:['Partner','#e2233f']};
  var st=document.getElementById('spStage'),dots=document.getElementById('spDots');
  function sortList(L){return ['gold','diamond','silver'].reduce(function(a,t){return a.concat(L.filter(function(s){return s.tier===t}))},[])
    .concat(L.filter(function(s){return !(s.tier in THEME)||s.tier==='other'}));}
  var order=sortList(SPONSORS);
  var start=Math.max(0,order.findIndex(function(s){return s.tier==='diamond'}));
  var n=order.length, act=start, pos=start, target=start, lock=false, built=false, cards=[], last=0, raf=0, tPrev=0, intro=null;
  var wDir=0, wCount=0, wT=0, shown=-1, infoT=0, info=document.getElementById('spInfo');
  function setInfo(i,instant){
    if(!n||!order[i]){info.innerHTML='';return;}
    var s=order[i],t=THEME[s.tier]||THEME.other;
    function put(){info.style.setProperty('--tc',t[1]);info.innerHTML='<div class="sc-name">'+esc(s.name)+'</div><div class="sc-tier">'+t[0]+' sponsor</div><p class="sc-quote">\u201C'+esc(s.quote)+'\u201D</p>';info.style.opacity=1;}
    clearTimeout(infoT); if(instant){put();return;} info.style.opacity=0; infoT=setTimeout(put,200);
  }
  /* ROW SHAPE: every sponsor sits on ONE long horizontal line, packed tight so they overlap (active one on top, the rest tucked behind it).
     ROW_STEP   = gap between neighbours as a fraction of the logo size (smaller = more crowded, more overlap, fewer slivers showing)
     ROW_SHRINK = how much smaller each step away from the centre gets
     ROW_DROOP  = how far the two ends of the line sag, as a fraction of the page width (0 = perfectly flat) */
  var ROW_STEP=.42 , ROW_SHRINK=.1, ROW_DROOP=.04;
  function wrapO(v){ v=((v%n)+n)%n; return v>=n/2?v-n:v; }
  function build(){
    st.innerHTML=order.map(function(s,i){var t=THEME[s.tier]||THEME.other;
      return '<div class="sc" data-i="'+i+'" style="--tc:'+t[1]+'"><div class="sc-logo">'+(s.logo?'<img src="'+esc(s.logo)+'" alt="'+esc(s.name)+'">':'<b>'+esc((s.name||'?')[0])+'</b>')+'</div>'
        +'<div class="sc-info"><div class="sc-name">'+esc(s.name)+'</div><div class="sc-tier">'+t[0]+' sponsor</div><p class="sc-quote">\u201C'+esc(s.quote)+'\u201D</p></div></div>';}).join('');
    cards=[].slice.call(st.children);
    cards.forEach(function(c){c.addEventListener('click',function(){go(+c.dataset.i)})});
    dots.innerHTML=order.map(function(s,i){return '<button type="button" data-i="'+i+'" aria-label="'+esc(s.name)+'"></button>'}).join('');
    [].forEach.call(dots.children,function(b){b.addEventListener('click',function(){go(+b.dataset.i)})});
    built=true;
  }
  function render(now){
    if(!n){info.innerHTML='';st.style.height='0px';return;}
    var W=st.clientWidth||innerWidth, U=parseFloat(getComputedStyle(st).getPropertyValue('--L'))||200;
    var step=U*ROW_STEP, hw=Math.max(step,W/2-(U*.3+10)), V=Math.max(1,Math.floor(hw/step));   /* V = sponsors that fit on each side of the centre */
    var L=Math.min(V,Math.floor((n-1)/2)), D=W*ROW_DROOP;
    st.style.height=(36+U+D+28)+'px';
    cards.forEach(function(c,i){
      var o=wrapO(i-pos), a=Math.abs(o), m=Math.min(a,V);
      var x=Math.max(-V,Math.min(V,o))*step, y=D*Math.pow(x/hw,2);
      var sc=Math.max(.42,1-ROW_SHRINK*m);
      var al=Math.max(0,Math.min(1,L+1-a));          /* sponsors past the end of the line fade out behind the last visible one */
      var e=1;
      if(intro){var p=Math.max(0,Math.min(1,(now-intro.t0-intro.d[i]*1000)/700)); e=1-Math.pow(1-p,3); x*=e; y*=e; sc*=.15+.85*e;}
      c.style.transform='translate3d('+x.toFixed(1)+'px,'+y.toFixed(1)+'px,0) scale('+sc.toFixed(3)+')';
      c.style.opacity=(e*al).toFixed(3);
      c.style.filter=m<.05?'none':'brightness('+Math.max(.5,1-.07*m).toFixed(2)+')';
      c.style.zIndex=Math.round(1000-a*10);
      c.style.pointerEvents=al<.05?'none':'auto';
      c.classList.toggle('on',a<.5);
    });
    [].forEach.call(dots.children,function(b,i){b.classList.toggle('on',i===act)});
    var near=((Math.round(pos)%n)+n)%n; if(near!==shown){shown=near;setInfo(near,false);}
  }
  function tick(now){
    raf=0; var dt=Math.min(.05,(now-tPrev)/1000)||.016; tPrev=now;
    var d=target-pos;
    if(Math.abs(d)>.0005){pos+=d*(1-Math.exp(-dt*7)); if(Math.abs(target-pos)<.0005)pos=target;}
    if(intro&&now-intro.t0>intro.end)intro=null;
    render(now);
    if(Math.abs(target-pos)>.0005||intro)raf=requestAnimationFrame(tick);
  }
  function kick(){ if(!raf){tPrev=performance.now(); raf=requestAnimationFrame(tick);} }
  function go(i){ if(lock||!n)return; i=((i%n)+n)%n; var d=Math.round(wrapO(i-target)); if(!d)return; target+=d; act=i; kick(); }
  st.addEventListener('wheel',function(e){
    var d=Math.abs(e.deltaY)>=Math.abs(e.deltaX)?e.deltaY:e.deltaX; if(!d)return;
    var dir=d>0?1:-1, t=Date.now();
    if(t-wT>700||dir!==wDir)wCount=0;
    wDir=dir; wT=t;
    if(wCount>=n)return;                       /* one full lap done: let the page scroll on */
    e.preventDefault();
    if(lock||t-last<420)return; last=t; wCount++; go(act+dir);
  },{passive:false});
  var tx=0,ty=0;
  st.addEventListener('touchstart',function(e){tx=e.touches[0].clientX;ty=e.touches[0].clientY},{passive:true});
  st.addEventListener('touchend',function(e){var dx=e.changedTouches[0].clientX-tx,dy=e.changedTouches[0].clientY-ty;if(Math.abs(dx)>40&&Math.abs(dx)>Math.abs(dy))go(act+(dx<0?1:-1))});
  st.addEventListener('keydown',function(e){if(e.key==='ArrowRight'||e.key==='ArrowDown'){e.preventDefault();go(act+1)}else if(e.key==='ArrowLeft'||e.key==='ArrowUp'){e.preventDefault();go(act-1)}});
  addEventListener('resize',function(){if(built)render(performance.now())});
  /* intro: diamond appears at the top centre -> silver (right) -> gold (left) -> the rest grow out of the centre and swing round the ring */
  window.setSponsors=function(L){
    var cur=order[act]&&order[act].id; order=sortList(L); n=order.length;
    start=Math.max(0,order.findIndex(function(s){return s.tier==='diamond'}));
    var k=cur?order.findIndex(function(s){return s.id===cur}):-1; act=k>=0?k:Math.min(start,Math.max(0,n-1));
    pos=target=act; build(); shown=-1; render(performance.now());
  };
  window.currentSponsor=function(){return order[act]};
  window.startSponsors=function(){
    if(!built)build();
    act=start; pos=target=start; lock=true;
    var reduce=matchMedia('(prefers-reduced-motion:reduce)').matches;
    var d=cards.map(function(c,i){var a=Math.abs(wrapO(i-start)),t=order[i].tier;
      return reduce?0:((a===0?0:(a===1&&t==='silver')?.55:(a===1&&t==='gold')?.85:1.15+a*.1));});
    intro=reduce?null:{t0:performance.now(),d:d,end:2300};
    shown=start; setInfo(start,true);
    render(performance.now()); kick();
    setTimeout(function(){lock=false},reduce?50:2300);
  };
})();
/* ---- sponsors: live data + on-page editing (saved through db, same as the rest of the site) ---- */
let sponsorDocs = [], thanksData = null, sponsorCount = -1;
function applySponsors() {
  const items = sponsorDocs.map(d => ({ id: d.id, name: d.name || 'Sponsor', tier: d.tier || 'other', logo: d.logoUrl || '', logoAssetId: d.logoAssetId || null, quote: d.quote || '', t: d.createdAt || 0 })).sort((a, b) => a.t - b.t);
  const prev = sponsorCount; sponsorCount = items.length; renderSponsorsAdmin(); window.setSponsors(items);
  if (prev <= 0 && items.length && document.getElementById('sponsors').offsetParent) window.startSponsors();
}
function renderThanks() {
  const t = thanksData || {};
  if (t.title) document.getElementById('thTitle').textContent = t.title;
  if (t.text) document.getElementById('thText').textContent = t.text;
  if (t.sign) document.getElementById('thSign').textContent = t.sign;
}
function renderSponsorsAdmin() {
  const has = sponsorCount > 0, g = id => document.getElementById(id);
  ['spStage', 'spInfo', 'spDots'].forEach(id => { const el = g(id); if (el) el.style.display = has ? '' : 'none'; });
  const em = g('spEmpty'); em.style.display = sponsorCount >= 0 && !has ? 'block' : 'none';
  em.querySelector('p').textContent = canEdit ? 'No sponsors yet. Click “＋ Add sponsor” below to add the first one.' : 'Our sponsors will appear here soon.';
  g('spAdmin').style.display = canEdit ? 'flex' : 'none';
  g('spEditBtn').style.display = g('spDelBtn').style.display = has ? '' : 'none';
  g('thEdit').style.display = canEdit ? '' : 'none';
}
function sponsorForm(ex) {
  openMini('sponsors', {
    title: ex ? 'Edit Sponsor' : 'New Sponsor', id: ex ? ex.id : null,
    fields: [
      { id: 'name', label: 'Sponsor name', type: 'text', v: ex ? ex.name : '' },
      { id: 'tier', label: 'Tier', type: 'select', v: ex ? ex.tier : 'other', options: [{ v: 'diamond', label: 'Diamond' }, { v: 'gold', label: 'Gold' }, { v: 'silver', label: 'Silver' }, { v: 'other', label: 'Partner' }] },
      { id: 'quote', label: 'Quote', type: 'textarea', v: ex ? ex.quote : '' },
      { id: 'logo', label: 'Logo (square image works best)', type: 'file', v: ex ? ex.logo : '', assetId: ex ? ex.logoAssetId : null },
    ],
  });
}
const SAMPLE_MSG = 'This is a sample sponsor. Use "Add sponsor" instead — the samples disappear once you add a real one.';
document.getElementById('spAdd').onclick = () => sponsorForm(null);
document.getElementById('spEditBtn').onclick = () => { const s = window.currentSponsor(); if (!s) return sponsorForm(null); if (!s.id) { alert(SAMPLE_MSG); return; } sponsorForm(s); };
document.getElementById('spDelBtn').onclick = async () => {
  const s = window.currentSponsor(); if (!s) return; if (!s.id) { alert(SAMPLE_MSG); return; }
  if (!dbNS || !confirm('Delete sponsor "' + s.name + '"?')) return;
  try { await dbNS.doc('sponsors/' + s.id).delete(); } catch (e) { alert('Delete error: ' + (e && (e.code || e.message))); }
};
document.getElementById('thEdit').onclick = () => openMini('thanks', {
  title: 'Edit Thank-you',
  fields: [
    { id: 'title', label: 'Heading', type: 'text', v: document.getElementById('thTitle').textContent },
    { id: 'text', label: 'Message', type: 'textarea', v: document.getElementById('thText').textContent },
    { id: 'sign', label: 'Signature', type: 'text', v: document.getElementById('thSign').textContent },
  ],
});
document.getElementById('navHome').addEventListener('click', e => {
  e.preventDefault();
  if (location.hash.replace(/^#/, '') === 'home' || !location.hash) showHome();
  else location.hash = 'home';
  window.scrollTo({ top: 0, behavior: 'smooth' });
});
document.getElementById('aboutBack').addEventListener('click', e => { e.preventDefault(); location.hash = 'home'; });
document.getElementById('spBack').addEventListener('click', () => { location.hash = 'seasons'; });

function mdLite(text) {
  let t = esc(text);
  t = t.replace(/\*\*(.+?)\*\*/g, '<b>$1</b>');
  t = t.replace(/(^|[^*])\*([^*]+?)\*(?!\*)/g, '$1<i>$2</i>');
  return t;
}
function logBodyHTML(blocks) {
  return (blocks || []).map(b => {
    if (b.type === 'heading') return `<h4>${esc(b.text)}</h4>`;
    if (b.type === 'image') return b.url ? `<figure><img src="${esc(b.url)}" alt="">${b.caption ? `<figcaption>${esc(b.caption)}</figcaption>` : ''}</figure>` : '';
    return b.text ? `<p>${mdLite(b.text)}</p>` : '';
  }).join('');
}
function fmtDateTime(ts) {
  if (!ts) return '—';
  const d = new Date(ts);
  return d.toLocaleDateString(undefined, { year: 'numeric', month: 'short', day: 'numeric' }) + ' at ' + d.toLocaleTimeString(undefined, { hour: '2-digit', minute: '2-digit' });
}

/* ---- side photo gallery + fullscreen lightbox ---- */
let lbPhotos = [], lbIndex = 0, currentSeasonPhotos = [];
function renderSpGallery2(s) {
  const photos = seasonPhotos(s);
  currentSeasonPhotos = photos;
  const grid = document.getElementById('spGallery2');
  if (!photos.length) { document.getElementById('spViewGallery').style.display = 'none';
    grid.outerHTML = '<div class="sp-empty-gallery" id="spGallery2">No photos yet.</div>'; return; }
  document.getElementById('spViewGallery').style.display = '';
  grid.outerHTML = `<div class="sp-gallery2" id="spGallery2">${photos.map((p, i) => `<div class="g-item${photos.length === 1 ? ' wide' : ''}" data-i="${i}"><img src="${esc(p.url)}" alt=""></div>`).join('')}</div>`;
  document.getElementById('spGallery2').querySelectorAll('.g-item').forEach(el => el.addEventListener('click', () => openLightbox(photos, +el.dataset.i)));
}
document.getElementById('spViewGallery').addEventListener('click', () => { if (currentSeasonPhotos.length) openLightbox(currentSeasonPhotos, 0); });
function openLightbox(photos, i) {
  lbPhotos = photos; lbIndex = i;
  renderLightbox();
  document.getElementById('lightboxOvl').classList.add('show');
}
function renderLightbox() {
  const p = lbPhotos[lbIndex]; if (!p) return;
  document.getElementById('lbImg').src = p.url;
  document.getElementById('lbFull').href = p.url;
  document.getElementById('lbStrip').innerHTML = lbPhotos.map((x, i) => `<img src="${esc(x.url)}" class="${i === lbIndex ? 'on' : ''}" data-i="${i}" alt="">`).join('');
  document.getElementById('lbStrip').querySelectorAll('img').forEach(el => el.addEventListener('click', () => { lbIndex = +el.dataset.i; renderLightbox(); }));
  const multi = lbPhotos.length > 1;
  document.getElementById('lbPrev').style.visibility = multi ? 'visible' : 'hidden';
  document.getElementById('lbNext').style.visibility = multi ? 'visible' : 'hidden';
}
function closeLightbox() { document.getElementById('lightboxOvl').classList.remove('show'); }
document.getElementById('lbClose').addEventListener('click', closeLightbox);
document.getElementById('lightboxOvl').addEventListener('click', e => { if (e.target.id === 'lightboxOvl') closeLightbox(); });
document.getElementById('lbPrev').addEventListener('click', () => { lbIndex = (lbIndex - 1 + lbPhotos.length) % lbPhotos.length; renderLightbox(); });
document.getElementById('lbNext').addEventListener('click', () => { lbIndex = (lbIndex + 1) % lbPhotos.length; renderLightbox(); });
addEventListener('keydown', e => {
  if (!document.getElementById('lightboxOvl').classList.contains('show')) return;
  if (e.key === 'Escape') closeLightbox();
  if (e.key === 'ArrowLeft') document.getElementById('lbPrev').click();
  if (e.key === 'ArrowRight') document.getElementById('lbNext').click();
});
document.getElementById('lbShareFb').addEventListener('click', () => window.open('https://www.facebook.com/sharer/sharer.php?u=' + encodeURIComponent(location.href), '_blank'));
document.getElementById('lbShareTw').addEventListener('click', () => window.open('https://twitter.com/intent/tweet?url=' + encodeURIComponent(location.href), '_blank'));

/* ---- season detail page ---- */
function openSeasonPage(id) {
  const s = seasons.find(x => x.id === id); if (!s) return;
  const banner = document.getElementById('spBanner');
  banner.innerHTML = s.bannerUrl ? `<img src="${esc(s.bannerUrl)}" alt="">` : `<span class="ph">${esc(s.name)}</span>`;
  renderSpGallery2(s);
  document.getElementById('spYear').textContent = s.year;
  document.getElementById('spName').textContent = s.name;
  document.getElementById('spOverview').textContent = s.overview || '—';
  document.getElementById('spSpecs').innerHTML = (s.specs || []).map(x => `<tr><td>${esc(x.k)}</td><td>${esc(x.v)}</td></tr>`).join('') || '<tr><td colspan="2">—</td></tr>';
  document.getElementById('spAch').innerHTML = (s.achievements || []).map(a => `<li><span style="color:var(--gold)">▸</span> ${esc(a)}</li>`).join('') || '<li>—</li>';
  const cad = document.getElementById('spCad'); if (s.cadLink) { cad.href = s.cadLink; cad.style.display = 'inline-block'; } else { cad.style.display = 'none'; }
  document.getElementById('spEdit').hidden = !canEdit; document.getElementById('spDelete').hidden = !canEdit;
  document.getElementById('spEdit').onclick = () => openForm(s);
  document.getElementById('spDelete').onclick = async () => { if (!dbNS || !confirm('Delete season "' + s.name + '"?')) return; await dbNS.doc('seasons/' + s.id).delete(); location.hash = 'seasons'; };

  /* description (notion-style blocks) */
  const descBody = document.getElementById('spDescBody');
  descBody.innerHTML = (s.descriptionBlocks && s.descriptionBlocks.length)
    ? s.descriptionBlocks.map(b => b.type === 'image' ? (b.url ? `<img src="${esc(b.url)}" alt="">` : '') : (b.text ? `<p>${esc(b.text)}</p>` : '')).join('')
    : '<p class="notion-empty">No description yet.</p>';
  document.getElementById('spDescEdit').hidden = !canEdit;
  document.getElementById('spDescEdit').onclick = () => openBodyEditor({ id: s.id, body: s.descriptionBlocks }, 'seasons/' + s.id, 'descriptionBlocks', () => openSeasonPage(s.id));

  /* files */
  renderSpFiles(s);

  /* logs */
  renderSpLogsOverview(s);

  showSeasonPageEl();
}

/* ---- files ---- */
function fileIcon(name) {
  const ext = (name || '').split('.').pop().toLowerCase();
  if (['png', 'jpg', 'jpeg', 'gif', 'webp'].includes(ext)) return '🖼️';
  if (['pdf'].includes(ext)) return '📄';
  if (['zip', 'rar', '7z'].includes(ext)) return '🗜️';
  if (['step', 'stp', 'glb', 'gltf', 'stl'].includes(ext)) return '📐';
  return '🔗';
}
function renderSpFiles(s) {
  const files = s.files || [];
  const list = document.getElementById('spFilesList');
  list.innerHTML = files.length ? files.map(f => `<div class="file-row" data-id="${f.id}">
      <a class="fi" href="${esc(f.url || f.link)}" target="_blank" rel="noopener">${fileIcon(f.name)}</a>
      <div class="fmeta"><a class="fname" href="${esc(f.url || f.link)}" target="_blank" rel="noopener">${esc(f.name || 'Untitled file')}</a><div class="fdate">Published ${fmtDateTime(f.addedAt)}</div></div>
      ${canEdit ? `<button type="button" class="frm" data-id="${f.id}">✕</button>` : ''}
    </div>`).join('') : '<p class="notion-empty">No files yet.</p>';
  list.querySelectorAll('.frm').forEach(b => b.addEventListener('click', async () => {
    if (!dbNS || !confirm('Remove this file?')) return;
    const nf = files.filter(f => f.id !== b.dataset.id);
    await dbNS.doc('seasons/' + s.id).update({ files: nf });
    s.files = nf; renderSpFiles(s);
  }));
  const addRow = document.getElementById('spFileAddRow');
  addRow.hidden = !canEdit;
  document.getElementById('spFileAddBtn').onclick = async () => {
    const name = document.getElementById('spFileName').value.trim();
    const link = document.getElementById('spFileLink').value.trim();
    const file = document.getElementById('spFileUpload').files[0];
    if (!name && !file) { alert('Please give the file a name.'); return; }
    let url = link || null, assetId = null;
    if (file && assetsNS) { try { const res = await assetsNS.upload(file); url = res.url; assetId = res.id; } catch (err) { alert('Image upload error: ' + (err && err.code)); return; } }
    if (!url) { alert('Add a link or upload a file.'); return; }
    const entry = { id: 'f_' + Date.now().toString(36) + Math.random().toString(36).slice(2, 7), name: name || (link ? link.split('/').pop() : 'File'), url, link, assetId, addedAt: Date.now() };
    const nf = [...(s.files || []), entry];
    if (!dbNS) { alert('Not connected to the database (db).'); return; }
    try {
      await dbNS.doc('seasons/' + s.id).update({ files: nf });
      s.files = nf;
      document.getElementById('spFileName').value = ''; document.getElementById('spFileLink').value = ''; document.getElementById('spFileUpload').value = '';
      renderSpFiles(s);
    } catch (err) { alert('Save error: ' + (err && (err.code || err.message))); }
  };
}

/* ---- project logs ---- */
function renderSpLogsOverview(s) {
  const logs = (s.logs || []).slice().sort((a, b) => b.createdAt - a.createdAt);
  const wrap = document.getElementById('spLogOverview');
  const latest = logs[0];
  wrap.innerHTML = latest ? `<div class="sl-log" style="border:0;margin:0;padding:0"><h4 class="log-title">${esc(latest.title)}</h4><div class="log-meta">${fmtDateTime(latest.createdAt)}</div><div class="log-body">${logBodyHTML(latest.blocks)}</div>${canEdit ? `<div class="log-admin"><button type="button" id="spLogEditBtn">✎ Edit</button><button type="button" id="spLogDelBtn">✕ Delete</button></div>` : ''}</div>`
    : '<p class="notion-empty">No project logs yet.</p>';
  if (latest && canEdit) {
    document.getElementById('spLogEditBtn').onclick = () => openLogEditor(s, latest);
    document.getElementById('spLogDelBtn').onclick = async () => {
      if (!dbNS || !confirm('Delete log "' + latest.title + '"?')) return;
      const nl = (s.logs || []).filter(l => l.id !== latest.id);
      await dbNS.doc('seasons/' + s.id).update({ logs: nl }); s.logs = nl; renderSpLogsOverview(s);
    };
  }
  const viewAllBtn = document.getElementById('spViewAllLogs');
  viewAllBtn.textContent = `View all ${logs.length} project log${logs.length === 1 ? '' : 's'}`;
  viewAllBtn.style.display = logs.length ? '' : 'none';
  viewAllBtn.onclick = () => { location.hash = 'season/' + s.id + '/logs'; };
  document.getElementById('spLogNew').hidden = !canEdit;
  document.getElementById('spLogNew').onclick = () => openLogEditor(s, null);
  const shareUrl = location.origin + location.pathname + '#season/' + s.id;
  document.getElementById('shareCopy').onclick = () => { navigator.clipboard && navigator.clipboard.writeText(shareUrl); const b = document.getElementById('shareCopy'); const old = b.textContent; b.textContent = '✓'; setTimeout(() => b.textContent = old, 1200); };
  document.getElementById('shareFb').onclick = () => window.open('https://www.facebook.com/sharer/sharer.php?u=' + encodeURIComponent(shareUrl), '_blank');
  document.getElementById('shareIg').onclick = () => { navigator.clipboard && navigator.clipboard.writeText(shareUrl); window.open('https://www.instagram.com/', '_blank'); };
}

let currentLogsSeasonId = null;
function openSeasonLogsPage(id) {
  const s = seasons.find(x => x.id === id); if (!s) return;
  currentLogsSeasonId = id;
  document.getElementById('slTitle').textContent = s.name + ' — Project Logs';
  document.getElementById('slBack').href = '#season/' + id;
  document.getElementById('slNew').hidden = !canEdit;
  document.getElementById('slNew').onclick = () => openLogEditor(s, null);
  renderSlList(s);
  document.getElementById('slSort').onchange = () => renderSlList(s);
  showSeasonLogsPageEl();
}
function renderSlList(s) {
  const dir = document.getElementById('slSort').value;
  const logs = (s.logs || []).slice().sort((a, b) => dir === 'oldest' ? a.createdAt - b.createdAt : b.createdAt - a.createdAt);
  document.getElementById('slList').innerHTML = logs.length ? logs.map(l => `<div class="sl-log" data-id="${l.id}"><h2 class="log-title">${esc(l.title)}</h2><div class="log-meta">${fmtDateTime(l.createdAt)}</div><div class="log-body">${logBodyHTML(l.blocks)}</div>${canEdit ? `<div class="log-admin"><button type="button" class="slEdit" data-id="${l.id}">✎ Edit</button><button type="button" class="slDel" data-id="${l.id}">✕ Delete</button></div>` : ''}</div>`).join('') : '<p class="notion-empty">No project logs yet.</p>';
  document.getElementById('slList').querySelectorAll('.slEdit').forEach(b => b.addEventListener('click', () => { const l = (s.logs || []).find(x => x.id === b.dataset.id); if (l) openLogEditor(s, l); }));
  document.getElementById('slList').querySelectorAll('.slDel').forEach(b => b.addEventListener('click', async () => {
    if (!dbNS || !confirm('Delete this log?')) return;
    const nl = (s.logs || []).filter(l => l.id !== b.dataset.id);
    await dbNS.doc('seasons/' + s.id).update({ logs: nl }); s.logs = nl; renderSlList(s);
  }));
}

/* ---- log editor: title + heading/paragraph(bold/italic)/image(caption) blocks ---- */
const logOvl = document.getElementById('logOvl');
let logBlocks = [], logSeasonId = null, logEditingId = null;
function wrapSelection(ta, mark) {
  const s = ta.selectionStart, e = ta.selectionEnd, v = ta.value;
  ta.value = v.slice(0, s) + mark + v.slice(s, e) + mark + v.slice(e);
  ta.dispatchEvent(new Event('input'));
  ta.focus(); ta.selectionStart = s + mark.length; ta.selectionEnd = e + mark.length;
}
function logBlockEditorHTML(b, i) {
  const handle = `<div class="block-handle"><button type="button" class="block-up" data-i="${i}">↑</button><button type="button" class="block-down" data-i="${i}">↓</button></div>`;
  if (b.type === 'image') {
    return `<div class="block-row"><input type="hidden">${handle}<div class="block-img">${b.url ? `<img src="${esc(b.url)}" alt="">` : ''}<input type="file" accept="image/*" class="block-imgfile" data-i="${i}"><input type="text" class="block-cap" data-i="${i}" placeholder="Image caption (optional)" value="${esc(b.caption || '')}"></div><button type="button" class="block-rm" data-i="${i}">✕</button></div>`;
  }
  if (b.type === 'heading') {
    return `<div class="block-row heading">${handle}<textarea class="block-text" data-i="${i}" placeholder="Heading text" rows="1">${esc(b.text || '')}</textarea><button type="button" class="block-rm" data-i="${i}">✕</button></div>`;
  }
  return `<div class="block-row">${handle}<div class="block-col"><div class="block-toolbar"><button type="button" class="block-b" data-i="${i}" title="Bold">B</button><button type="button" class="block-i" data-i="${i}" title="Italic"><i>I</i></button></div><textarea class="block-text" data-i="${i}" placeholder="Write a paragraph... (select text and use B/I to format)">${esc(b.text || '')}</textarea></div><button type="button" class="block-rm" data-i="${i}">✕</button></div>`;
}
function renderLogBlocks() {
  document.getElementById('logBlocks').innerHTML = logBlocks.map(logBlockEditorHTML).join('') || '<p style="color:var(--ink3);font-size:12px;margin:0 0 12px">No content yet — add a heading, paragraph or image below.</p>';
  const el = document.getElementById('logBlocks');
  el.querySelectorAll('.block-text').forEach(t => t.addEventListener('input', () => { logBlocks[+t.dataset.i].text = t.value; }));
  el.querySelectorAll('.block-rm').forEach(b => b.addEventListener('click', () => { logBlocks.splice(+b.dataset.i, 1); renderLogBlocks(); }));
  el.querySelectorAll('.block-up').forEach(b => b.addEventListener('click', () => { const i = +b.dataset.i; if (i > 0) { [logBlocks[i - 1], logBlocks[i]] = [logBlocks[i], logBlocks[i - 1]]; renderLogBlocks(); } }));
  el.querySelectorAll('.block-down').forEach(b => b.addEventListener('click', () => { const i = +b.dataset.i; if (i < logBlocks.length - 1) { [logBlocks[i + 1], logBlocks[i]] = [logBlocks[i], logBlocks[i + 1]]; renderLogBlocks(); } }));
  el.querySelectorAll('.block-b').forEach(b => b.addEventListener('click', () => wrapSelection(el.querySelector(`.block-text[data-i="${b.dataset.i}"]`), '**')));
  el.querySelectorAll('.block-i').forEach(b => b.addEventListener('click', () => wrapSelection(el.querySelector(`.block-text[data-i="${b.dataset.i}"]`), '*')));
  el.querySelectorAll('.block-cap').forEach(inp => inp.addEventListener('input', () => { logBlocks[+inp.dataset.i].caption = inp.value; }));
  el.querySelectorAll('.block-imgfile').forEach(inp => inp.addEventListener('change', async e => {
    const file = e.target.files[0]; if (!file || !assetsNS) return;
    try { const res = await assetsNS.upload(file); logBlocks[+inp.dataset.i] = { type: 'image', assetId: res.id, url: res.url, caption: logBlocks[+inp.dataset.i].caption || '' }; renderLogBlocks(); }
    catch (err) { alert('Image upload error: ' + (err && err.code)); }
  }));
}
function openLogEditor(s, existing) {
  logSeasonId = s.id; logEditingId = existing ? existing.id : null;
  document.getElementById('logOvlTitle').textContent = existing ? 'Edit Log' : 'New Log';
  document.getElementById('logTitleInput').value = existing ? existing.title : '';
  logBlocks = existing && existing.blocks ? existing.blocks.map(b => ({ ...b })) : [];
  renderLogBlocks();
  showOvl(logOvl);
}
document.getElementById('logAddHeading').addEventListener('click', () => { logBlocks.push({ type: 'heading', text: '' }); renderLogBlocks(); });
document.getElementById('logAddText').addEventListener('click', () => { logBlocks.push({ type: 'text', text: '' }); renderLogBlocks(); });
document.getElementById('logAddImg').addEventListener('click', () => { logBlocks.push({ type: 'image', url: '', assetId: null, caption: '' }); renderLogBlocks(); });
document.getElementById('logClose').addEventListener('click', () => closeOvl(logOvl));
document.getElementById('logCancel').addEventListener('click', () => closeOvl(logOvl));
logOvl.addEventListener('click', e => { if (e.target === logOvl) closeOvl(logOvl); });
document.getElementById('logSave').addEventListener('click', async () => {
  if (!dbNS || !logSeasonId) return;
  const title = document.getElementById('logTitleInput').value.trim() || 'Untitled log';
  const clean = logBlocks.filter(b => b.type === 'image' ? b.url : b.text.trim());
  const s = seasons.find(x => x.id === logSeasonId); if (!s) return;
  let logs = (s.logs || []).slice();
  try {
    if (logEditingId) { const i = logs.findIndex(l => l.id === logEditingId); if (i > -1) logs[i] = { ...logs[i], title, blocks: clean }; }
    else logs.push({ id: 'log_' + Date.now().toString(36) + Math.random().toString(36).slice(2, 7), title, blocks: clean, createdAt: Date.now() });
    await dbNS.doc('seasons/' + logSeasonId).update({ logs });
    s.logs = logs;
    closeOvl(logOvl);
    if (document.getElementById('seasonLogsPage').classList.contains('show')) renderSlList(s); else renderSpLogsOverview(s);
  } catch (err) { alert('Save error: ' + (err && (err.code || err.message))); }
});

let pendingSeasonId = null, pendingLogsSeasonId = null;
function tryOpenPending() {
  if (pendingSeasonId && seasons.some(s => s.id === pendingSeasonId)) { const id = pendingSeasonId; pendingSeasonId = null; openSeasonPage(id); }
  if (pendingLogsSeasonId && seasons.some(s => s.id === pendingLogsSeasonId)) { const id = pendingLogsSeasonId; pendingLogsSeasonId = null; openSeasonLogsPage(id); }
}
function updateNavActive(page) {
  document.querySelectorAll('#nav nav a').forEach(a => a.classList.toggle('on', a.getAttribute('href') === '#' + page));
}
function routeHash() {
  const h = location.hash.replace(/^#/, '');
  if (h.startsWith('season/')) {
    const rest = decodeURIComponent(h.slice(7));
    if (rest.endsWith('/logs')) {
      const id = rest.slice(0, -5);
      if (seasons.some(s => s.id === id)) openSeasonLogsPage(id); else pendingLogsSeasonId = id;
    } else if (seasons.some(s => s.id === rest)) openSeasonPage(rest); else pendingSeasonId = rest;
    updateNavActive('seasons');
  }
  else if (h.startsWith('resource/')) { const id = decodeURIComponent(h.slice(9)); if (resources.some(r => r.id === id)) openResourcePage(id); else pendingResourceId = id; updateNavActive('resources'); }
  else if (h === 'about') { showAboutPageEl(); updateNavActive('about'); }
  else if (h === 'seasons') { showSeasonsListEl(); updateNavActive('seasons'); }
  else if (h === 'resources') { showResourcesListEl(); updateNavActive('resources'); }
  else if (h === 'sponsors') { showSponsorsEl(); updateNavActive('sponsors'); }
  else { showHome(); updateNavActive('home'); }
}
addEventListener('hashchange', routeHash);

/* ---- form overlay (create/edit season) ---- */
const formOvl = document.getElementById('formOvl');
function showOvl(el) { el.classList.add('show'); }
function closeOvl(el) { el.classList.remove('show'); }
formOvl.addEventListener('click', e => { if (e.target === formOvl) closeOvl(formOvl); });
function rowHTML(val, ph1, ph2) { return `<div class="r"><input placeholder="${ph1}" value="${esc(val && val.k !== undefined ? val.k : (val || ''))}" data-f="k"><input placeholder="${ph2 || ''}" value="${esc(val && val.v !== undefined ? val.v : '')}" data-f="v" ${ph2 ? '' : 'style="display:none"'}><button type="button" class="rm">✕</button></div>`; }
function renderSpecRows() { document.getElementById('fSpecs').innerHTML = fSpecsRows.map(r => rowHTML(r, 'Spec (e.g. Weight)', 'Value (e.g. 11 kg)')).join(''); wireRows('fSpecs', fSpecsRows); }
function renderAchRows() { document.getElementById('fAch').innerHTML = fAchRows.map(r => rowHTML({ k: r }, 'e.g. Inspire Award — Da Nang Qualifier')).join(''); wireRows('fAch', fAchRows, true); }
function wireRows(id, arr, simple) {
  const el = document.getElementById(id);
  el.querySelectorAll('.r').forEach((row, i) => {
    row.querySelectorAll('input').forEach(inp => inp.addEventListener('input', () => {
      if (simple) arr[i] = row.querySelector('input').value; else { arr[i] = arr[i] || {}; arr[i][inp.dataset.f] = inp.value; }
    }));
    row.querySelector('.rm').addEventListener('click', () => { arr.splice(i, 1); simple ? renderAchRows() : renderSpecRows(); });
  });
}
document.getElementById('fSpecAdd').addEventListener('click', () => { fSpecsRows.push({ k: '', v: '' }); renderSpecRows(); });
document.getElementById('fAchAdd').addEventListener('click', () => { fAchRows.push(''); renderAchRows(); });

function openForm(existing) {
  editingId = existing ? existing.id : null;
  document.getElementById('fTitle').textContent = existing ? 'Edit Season' : 'New Season';
  document.getElementById('fName').value = existing ? existing.name : '';
  document.getElementById('fYear').value = existing ? existing.year : '';
  document.getElementById('fOverview').value = existing ? (existing.overview || '') : '';
  document.getElementById('fCad').value = existing ? (existing.cadLink || '') : '';
  fAlbumPhotos = existing ? seasonPhotos(existing).map(p => ({ ...p })) : [];
  renderAlbumPrev();
  fBannerAssetId = existing ? (existing.bannerAssetId || null) : null;
  document.getElementById('fBannerPrev').src = existing && existing.bannerUrl ? existing.bannerUrl : '';
  fSpecsRows = existing && existing.specs ? existing.specs.map(s => ({ ...s })) : [{ k: '', v: '' }];
  fAchRows = existing && existing.achievements ? [...existing.achievements] : [''];
  renderSpecRows(); renderAchRows();
  showOvl(formOvl);
}
document.getElementById('fClose').addEventListener('click', () => closeOvl(formOvl));
document.getElementById('fCancel').addEventListener('click', () => closeOvl(formOvl));
function renderAlbumPrev() {
  const el = document.getElementById('fAlbumPrev');
  el.innerHTML = fAlbumPhotos.map((p, i) => `<div class="album-thumb reorder"><img src="${esc(p.url)}" alt="">${i === 0 ? '<span class="cover-badge">COVER</span>' : ''}<div class="ord">${i > 0 ? `<button type="button" class="ord-up" data-i="${i}">↑</button>` : ''}${i < fAlbumPhotos.length - 1 ? `<button type="button" class="ord-down" data-i="${i}">↓</button>` : ''}</div><button type="button" class="album-rm" data-i="${i}">✕</button></div>`).join('');
  el.querySelectorAll('.album-rm').forEach(b => b.addEventListener('click', () => { fAlbumPhotos.splice(+b.dataset.i, 1); renderAlbumPrev(); }));
  el.querySelectorAll('.ord-up').forEach(b => b.addEventListener('click', () => { const i = +b.dataset.i; [fAlbumPhotos[i - 1], fAlbumPhotos[i]] = [fAlbumPhotos[i], fAlbumPhotos[i - 1]]; renderAlbumPrev(); }));
  el.querySelectorAll('.ord-down').forEach(b => b.addEventListener('click', () => { const i = +b.dataset.i; [fAlbumPhotos[i + 1], fAlbumPhotos[i]] = [fAlbumPhotos[i], fAlbumPhotos[i + 1]]; renderAlbumPrev(); }));
}
document.getElementById('fAlbumFile').addEventListener('change', async e => {
  const files = Array.from(e.target.files || []); if (!files.length || !assetsNS) return;
  for (const file of files) {
    try { const res = await assetsNS.upload(file); fAlbumPhotos.push({ assetId: res.id, url: res.url }); }
    catch (err) { alert('Image upload error: ' + (err && err.code)); }
  }
  renderAlbumPrev();
  e.target.value = '';
});
document.getElementById('fBannerFile').addEventListener('change', async e => {
  const file = e.target.files[0]; if (!file || !assetsNS) return;
  const prev = document.getElementById('fBannerPrev');
  try {
    const res = await assetsNS.upload(file);
    fBannerAssetId = res.id;
    prev.src = res.url;
  } catch (err) {
    alert('Image upload error: ' + (err && err.code));
  }
  e.target.value = '';
});
document.getElementById('seasonForm').addEventListener('submit', async e => {
  e.preventDefault();
  if (!dbNS) { alert('Not connected to the database (db).'); return; }
  const data = {
    name: document.getElementById('fName').value.trim() || 'Untitled season',
    year: document.getElementById('fYear').value.trim(),
    overview: document.getElementById('fOverview').value,
    cadLink: document.getElementById('fCad').value.trim(),
    specs: fSpecsRows.filter(s => s.k || s.v),
    achievements: fAchRows.filter(Boolean),
    photos: fAlbumPhotos.map(p => ({ assetId: p.assetId, url: p.url })),
    bannerAssetId: fBannerAssetId, bannerUrl: blobUrl(fBannerAssetId, document.getElementById('fBannerPrev').getAttribute('src') || null),
    updatedAt: Date.now(),
  };
  try {
    if (editingId) await dbNS.doc('seasons/' + editingId).update(data);
    else { data.createdAt = Date.now(); data.descriptionBlocks = []; data.files = []; data.logs = []; await dbNS.collection('seasons').add(data); }
    closeOvl(formOvl);
  } catch (err) { alert('Save error: ' + (err && (err.code || err.message))); }
});

/* ---------------- Resources (grouped by category, headline-only list -> detail page) ---------------- */
let resources = [], pendingResourceId = null;
function resourceCardHTML(r) {
  return `<button type="button" class="resource-card" data-id="${r.id}">${esc(r.title)}</button>`;
}
function renderResources() {
  const groups = []; const byKey = {};
  resources.forEach(r => {
    const label = (r.category || 'Other').trim() || 'Other';
    const key = label.toLowerCase();
    if (!byKey[key]) { byKey[key] = { label, items: [] }; groups.push(byKey[key]); }
    byKey[key].items.push(r);
  });
  const add = canEdit ? `<button type="button" class="robot-new" id="btnNewResource" style="margin-bottom:22px;min-height:70px;flex-direction:row;justify-content:center;gap:10px;padding:10px 16px;width:max-content"><span class="plus">+</span><span>New Resource</span></button>` : '';
  const body = groups.length
    ? groups.map(g => `<div class="team-cat"><h4 class="team-cat-title">${esc(g.label)}</h4><div class="mini-grid">${g.items.map(resourceCardHTML).join('')}</div></div>`).join('')
    : (canEdit ? '' : '<p style="color:var(--ink3)">No resources yet.</p>');
  document.getElementById('resourceGroups').innerHTML = add + body;
  const nb = document.getElementById('btnNewResource'); if (nb) nb.addEventListener('click', () => openResourceForm(null));
  document.getElementById('resourceGroups').querySelectorAll('.resource-card').forEach(c => c.addEventListener('click', () => { location.hash = 'resource/' + c.dataset.id; }));
  if (pendingResourceId && resources.some(r => r.id === pendingResourceId)) { const id = pendingResourceId; pendingResourceId = null; openResourcePage(id); }
}
function openResourcePage(id) {
  const r = resources.find(x => x.id === id); if (!r) return;
  document.getElementById('rpTitle').textContent = r.title;
  document.getElementById('rpCategory').textContent = r.category || '';
  const rpBody = document.getElementById('rpBody');
  rpBody.innerHTML = (r.body && r.body.length)
    ? r.body.map(b => b.type === 'image' ? `<img src="${esc(b.url)}" alt="">` : `<p>${esc(b.text)}</p>`).join('')
    : `<p>${esc(r.desc || '—')}</p>`;
  const link = document.getElementById('rpLink');
  if (r.link) { link.href = r.link; link.style.display = 'inline-block'; } else { link.style.display = 'none'; }
  document.getElementById('rpEdit').hidden = !canEdit;
  document.getElementById('rpDelete').hidden = !canEdit;
  document.getElementById('rpEditBody').hidden = !canEdit;
  document.getElementById('rpEdit').onclick = () => openResourceForm(r);
  document.getElementById('rpEditBody').onclick = () => openBodyEditor(r);
  document.getElementById('rpDelete').onclick = async () => { if (!dbNS || !confirm('Delete "' + r.title + '"?')) return; await dbNS.doc('resources/' + r.id).delete(); location.hash = 'resources'; };
  showResourcePageEl();
}

/* ---- block content editor: mix paragraphs + images, in any order ---- */
const bodyOvl = document.getElementById('bodyOvl');
let bodyBlocks = [], bodyResourceId = null;
function blockEditorHTML(b, i) {
  const handle = `<div class="block-handle"><button type="button" class="block-up" data-i="${i}">↑</button><button type="button" class="block-down" data-i="${i}">↓</button></div>`;
  if (b.type === 'image') {
    return `<div class="block-row"><input type="hidden">${handle}<div class="block-img">${b.url ? `<img src="${esc(b.url)}" alt="">` : ''}<input type="file" accept="image/*" class="block-imgfile" data-i="${i}"></div><button type="button" class="block-rm" data-i="${i}">✕</button></div>`;
  }
  return `<div class="block-row">${handle}<textarea class="block-text" data-i="${i}" placeholder="Write a paragraph...">${esc(b.text || '')}</textarea><button type="button" class="block-rm" data-i="${i}">✕</button></div>`;
}
function renderBodyBlocks() {
  document.getElementById('bodyBlocks').innerHTML = bodyBlocks.map(blockEditorHTML).join('') || '<p style="color:var(--ink3);font-size:12px;margin:0 0 12px">No content yet — add a paragraph or image below.</p>';
  const el = document.getElementById('bodyBlocks');
  el.querySelectorAll('.block-text').forEach(t => t.addEventListener('input', () => { bodyBlocks[+t.dataset.i].text = t.value; }));
  el.querySelectorAll('.block-rm').forEach(b => b.addEventListener('click', () => { bodyBlocks.splice(+b.dataset.i, 1); renderBodyBlocks(); }));
  el.querySelectorAll('.block-up').forEach(b => b.addEventListener('click', () => { const i = +b.dataset.i; if (i > 0) { [bodyBlocks[i - 1], bodyBlocks[i]] = [bodyBlocks[i], bodyBlocks[i - 1]]; renderBodyBlocks(); } }));
  el.querySelectorAll('.block-down').forEach(b => b.addEventListener('click', () => { const i = +b.dataset.i; if (i < bodyBlocks.length - 1) { [bodyBlocks[i + 1], bodyBlocks[i]] = [bodyBlocks[i], bodyBlocks[i + 1]]; renderBodyBlocks(); } }));
  el.querySelectorAll('.block-imgfile').forEach(inp => inp.addEventListener('change', async e => {
    const file = e.target.files[0]; if (!file || !assetsNS) return;
    try { const res = await assetsNS.upload(file); bodyBlocks[+inp.dataset.i] = { type: 'image', assetId: res.id, url: res.url }; renderBodyBlocks(); }
    catch (err) { alert('Image upload error: ' + (err && err.code)); }
  }));
}
/* generic: works for any doc's block-array field (resources.body, seasons.descriptionBlocks, ...) */
let bodyPath = null, bodyKey = null, bodyAfterSave = null;
function openBodyEditor(r, path, key, afterSave) {
  bodyPath = path || ('resources/' + r.id);
  bodyKey = key || 'body';
  bodyAfterSave = afterSave || (() => openResourcePage(r.id));
  bodyBlocks = (r.body && r.body.length) ? r.body.map(b => ({ ...b })) : (r.desc ? [{ type: 'text', text: r.desc }] : []);
  renderBodyBlocks();
  showOvl(bodyOvl);
}
document.getElementById('bodyAddText').addEventListener('click', () => { bodyBlocks.push({ type: 'text', text: '' }); renderBodyBlocks(); });
document.getElementById('bodyAddImg').addEventListener('click', () => { bodyBlocks.push({ type: 'image', url: '', assetId: null }); renderBodyBlocks(); });
document.getElementById('bodyClose').addEventListener('click', () => closeOvl(bodyOvl));
document.getElementById('bodyCancel').addEventListener('click', () => closeOvl(bodyOvl));
bodyOvl.addEventListener('click', e => { if (e.target === bodyOvl) closeOvl(bodyOvl); });
document.getElementById('bodySave').addEventListener('click', async () => {
  if (!dbNS || !bodyPath) return;
  const clean = bodyBlocks.filter(b => b.type === 'text' ? b.text.trim() : b.url);
  try {
    await dbNS.doc(bodyPath).update({ [bodyKey]: clean });
    if (bodyPath.startsWith('resources/')) { const r = resources.find(x => x.id === bodyPath.slice(10)); if (r) r.body = clean; }
    else if (bodyPath.startsWith('seasons/')) { const s = seasons.find(x => x.id === bodyPath.slice(8)); if (s) s.descriptionBlocks = clean; }
    closeOvl(bodyOvl);
    if (bodyAfterSave) bodyAfterSave();
  } catch (err) { alert('Save error: ' + (err && (err.code || err.message))); }
});
