function contactDisplay(c) {
  const isEmail = v => /\S+@\S+\.\S+/.test(v || '');
  const isPhone = v => /^[+]?[\d][\d\s().-]{6,}$/.test((v || '').trim());
  const cands = [c.value, c.label].filter(Boolean);
  const email = cands.find(isEmail);
  if (email) return { tag: 'Email', main: email, link: c.link || ('mailto:' + email) };
  const phone = cands.find(isPhone);
  if (phone) return { tag: 'Phone', main: phone, link: c.link || ('tel:' + phone.replace(/[^\d+]/g, '')) };
  return { tag: c.label || 'Contact', main: c.value || '', link: c.link || '' };
}
function renderContacts() {
  const cards = contacts.map(c => {
    const d = contactDisplay(c);
    const mainHTML = d.link ? `<a class="cvalue" href="${esc(d.link)}" target="_blank" rel="noopener">${esc(d.main)}</a>` : `<b class="cvalue">${esc(d.main)}</b>`;
    return `<div class="contact-card">
      ${canEdit ? `<div class="card-admin"><button data-a="e" data-id="${c.id}">✎</button><button data-a="d" data-id="${c.id}">✕</button></div>` : ''}
      <span class="clabel">${esc(d.tag)}</span>${mainHTML}
    </div>`;
  }).join('');
  const add = canEdit ? `<button type="button" class="robot-new" id="btnNewContact"><span class="plus">+</span><span>New Contact</span></button>` : '';
  document.getElementById('contactGrid').innerHTML = add + cards;
  wireMiniAdmin('contactGrid', 'contacts', contacts);
  const nb = document.getElementById('btnNewContact'); if (nb) nb.addEventListener('click', () => openContactForm(null));
}

