function detectPlatform(s) {
  const t = ((s.link || '') + ' ' + (s.platform || '')).toLowerCase();
  const table = [['youtube', 'youtube'], ['youtu.be', 'youtube'], ['facebook', 'facebook'], ['fb.com', 'facebook'], ['instagram', 'instagram'], ['tiktok', 'tiktok'], ['twitter', 'x'], ['x.com', 'x'], ['discord', 'discord'], ['github', 'github'], ['linkedin', 'linkedin'], ['t.me', 'telegram'], ['telegram', 'telegram'], ['zalo', 'zalo'], ['twitch', 'twitch'], ['threads', 'threads']];
  const hit = table.find(([k]) => t.includes(k));
  return hit ? hit[1] : 'website';
}
function socialThumbHTML(s) {
  if (s.logoUrl) return `<img src="${esc(s.logoUrl)}" alt="">`;
  const key = detectPlatform(s);
  return `<svg viewBox="0 0 24 24">${PLATFORM_ICONS[key]}</svg>`;
}
