function wireMiniAdmin(gridId, coll, arr) {
  document.getElementById(gridId).querySelectorAll('[data-a]').forEach(btn => {
    btn.addEventListener('click', async () => {
      const id = btn.dataset.id, item = arr.find(x => x.id === id);
      if (btn.dataset.a === 'd') { if (dbNS && confirm('Delete this item?')) await dbNS.doc(coll + '/' + id).delete(); }
      else { if (coll === 'teammates') openTeamForm(item); else if (coll === 'contacts') openContactForm(item); else if (coll === 'mentors') openMentorForm(item); else openSocialForm(item); }
    });
  });
}

