/* ---- Supabase Storage (ảnh/file) ---- */
function blobUrl(id, fallback) {
  if (!id || !sb) return fallback || '';
  return sb.storage.from(SB_BUCKET).getPublicUrl(id).data.publicUrl;
}
function compressImage(file) {
  /* thu nhỏ ảnh lớn (tối đa 2000px) trước khi upload; gif/svg giữ nguyên. Trả về Blob hoặc null */
  return new Promise(resolve => {
    if (!file.type.startsWith('image/') || /gif|svg/.test(file.type)) { resolve(null); return; }
    const url = URL.createObjectURL(file); const img = new Image();
    img.onload = () => {
      try {
        const M = 2000, k = Math.min(1, M / Math.max(img.naturalWidth, img.naturalHeight));
        const c = document.createElement('canvas'); c.width = Math.round(img.naturalWidth * k); c.height = Math.round(img.naturalHeight * k);
        c.getContext('2d').drawImage(img, 0, 0, c.width, c.height);
        URL.revokeObjectURL(url);
        c.toBlob(b => {
          if (b && b.type === 'image/webp') { resolve(b); return; }
          c.toBlob(b2 => resolve(b2), 'image/jpeg', .86);
        }, 'image/webp', .86);
      } catch (e) { URL.revokeObjectURL(url); resolve(null); }
    };
    img.onerror = () => { URL.revokeObjectURL(url); resolve(null); };
    img.src = url;
  });
}
function SupabaseAssets() {
  return {
    async upload(file) {
      let body = file, type = file.type || 'application/octet-stream';
      const cmp = await compressImage(file);
      if (cmp) { body = cmp; type = cmp.type; }
      const ext = cmp ? (type === 'image/webp' ? 'webp' : 'jpg') : ((file.name.split('.').pop() || 'bin').toLowerCase().replace(/[^a-z0-9]/g, '').slice(0, 8) || 'bin');
      const id = 'uploads/' + Date.now().toString(36) + '_' + Math.random().toString(36).slice(2, 8) + '.' + ext;
      const { error } = await sb.storage.from(SB_BUCKET).upload(id, body, { contentType: type, cacheControl: '31536000', upsert: false });
      if (error) { const e = new Error(error.message); e.code = error.statusCode || error.message; throw e; }
      return { id, url: blobUrl(id) };
    }
  };
}

/* ---- Supabase Database: bảng public.docs (collection, id, data jsonb) + realtime ----
   Giữ nguyên API collection()/doc()/onSnapshot() mà phần còn lại của code đang dùng. */
function SupabaseDB() {
  const listeners = {}, mem = {}; let loadErr = null;
  const get = c => (mem[c] = mem[c] || []);
  const notify = c => (listeners[c] || []).slice().forEach(fn => fn());
  const fail = error => { const e = new Error(error.message); e.code = error.code || error.message; return e; };
  const applyRow = row => { const arr = get(row.collection); const rec = { id: row.id, ...row.data }; const i = arr.findIndex(d => d.id === row.id); if (i >= 0) arr[i] = rec; else arr.push(rec); };
  const toSnap = arr => ({ docs: arr.map(d => ({ id: d.id, data: () => { const { id, ...rest } = d; return rest; } })) });
  const newId = () => (crypto.randomUUID ? crypto.randomUUID() : 'id_' + Date.now().toString(36) + Math.random().toString(36).slice(2, 10));

  const ready = (async () => {
    for (let from = 0; ; from += 1000) {
      const { data, error } = await sb.from('docs').select('collection,id,data').order('collection').order('id').range(from, from + 999);
      if (error) { loadErr = fail(error); console.error('Supabase load error:', error); return; }
      data.forEach(applyRow);
      if (data.length < 1000) break;
    }
  })();

  sb.channel('docs-sync').on('postgres_changes', { event: '*', schema: 'public', table: 'docs' }, p => {
    if (p.eventType === 'DELETE') {
      const o = p.old; if (!o || !o.collection || !o.id) return;
      mem[o.collection] = get(o.collection).filter(d => d.id !== o.id); notify(o.collection);
    } else if (p.new && p.new.collection) { applyRow(p.new); notify(p.new.collection); }
  }).subscribe();

  const write = async (c, id, data) => {
    await ready;
    const { id: _drop, ...clean } = data || {};
    const { error } = await sb.from('docs').upsert({ collection: c, id, data: clean, updated_at: new Date().toISOString() });
    if (error) throw fail(error);
    applyRow({ collection: c, id, data: clean }); notify(c);
  };
  const remove = async (c, id) => {
    await ready;
    const { data, error } = await sb.from('docs').delete().eq('collection', c).eq('id', id).select('id');
    if (error) throw fail(error);
    if (!data.length && get(c).some(d => d.id === id)) { const e = new Error('Not allowed'); e.code = 'permission-denied'; throw e; }
    mem[c] = get(c).filter(d => d.id !== id); notify(c);
  };
  const subscribe = (c, fn, errCb) => {
    ready.then(() => {
      if (loadErr && errCb) { errCb(loadErr); return; }
      (listeners[c] = listeners[c] || []).push(fn); fn();
    });
    return () => { listeners[c] = (listeners[c] || []).filter(f => f !== fn); };
  };

  return {
    ready,
    collection(c) {
      let order = null;
      const api = {
        orderBy(field, dir) { order = { field, dir }; return api; },
        async add(data) { const id = newId(); await write(c, id, data); return { id }; },
        onSnapshot(cb, errCb) {
          return subscribe(c, () => {
            const arr = [...get(c)];
            if (order) arr.sort((a, b) => order.dir === 'desc' ? (b[order.field] || 0) - (a[order.field] || 0) : (a[order.field] || 0) - (b[order.field] || 0));
            cb(toSnap(arr));
          }, errCb);
        }
      };
      return api;
    },
    doc(path) {
      const i = path.indexOf('/'); const c = i === -1 ? path : path.slice(0, i); const id = i === -1 ? null : path.slice(i + 1);
      return {
        set(data) { return write(c, id, data); },
        update(patch) { const cur = get(c).find(d => d.id === id) || {}; const { id: _i, ...rest } = cur; return write(c, id, { ...rest, ...patch }); },
        delete() { return remove(c, id); },
        onSnapshot(cb, errCb) {
          return subscribe(c, () => {
            const rec = get(c).find(d => d.id === id);
            cb({ exists: !!rec, data: () => { if (!rec) return undefined; const { id: _id, ...rest } = rec; return rest; } });
          }, errCb);
        }
      };
    }
  };
}

