routeHash();
(async function boot() {
  if (sb) {
    try { const { data } = await sb.auth.getSession(); if (data && data.session) { if (await checkIsAdmin()) { pwOn = true; canEdit = true; } else { await sb.auth.signOut(); } } } catch (e) {}
    sb.auth.onAuthStateChange(ev => { if (ev === 'SIGNED_OUT' && canEdit) location.reload(); });
  }
  refreshAdminUI();
  if (sb) { assetsNS = SupabaseAssets(); dbNS = SupabaseDB(); }
  try {
    if (dbNS) {
      dbNS.collection('seasons').orderBy('createdAt', 'desc').onSnapshot(
        snap => { seasons = snap.docs.map(d => ({ id: d.id, ...d.data() })); renderSeasons(); },
        () => { renderSeasons(); }
      );
      dbNS.doc('about/main').onSnapshot(
        snap => { if (snap.exists) aboutData = { ...aboutData, ...snap.data() }; renderAbout(); },
        () => renderAbout()
      );
      dbNS.doc('homestats/main').onSnapshot(
        snap => { if (snap.exists) homeStats = { ...homeStats, ...snap.data() }; renderHomeStats(); },
        () => renderHomeStats()
      );
      dbNS.doc('director/main').onSnapshot(
        snap => { directorData = snap.exists ? snap.data() : null; renderDirector(); },
        () => renderDirector()
      );
      dbNS.collection('mentors').onSnapshot(snap => { mentors = snap.docs.map(d => ({ id: d.id, ...d.data() })); renderMentors(); }, () => renderMentors());
      dbNS.collection('teammates').onSnapshot(snap => { teammates = snap.docs.map(d => ({ id: d.id, ...d.data() })); renderTeam(); }, () => renderTeam());
      dbNS.collection('contacts').onSnapshot(snap => { contacts = snap.docs.map(d => ({ id: d.id, ...d.data() })); renderContacts(); }, () => renderContacts());
      dbNS.collection('sponsors').onSnapshot(snap => { sponsorDocs = snap.docs.map(d => ({ id: d.id, ...d.data() })); applySponsors(); }, () => applySponsors());
      dbNS.doc('thanks/main').onSnapshot(snap => { thanksData = snap.exists ? snap.data() : null; renderThanks(); }, () => renderThanks());
      dbNS.collection('socials').onSnapshot(snap => { socials = snap.docs.map(d => ({ id: d.id, ...d.data() })); renderSocials(); }, () => renderSocials());
      dbNS.collection('resources').orderBy('createdAt', 'desc').onSnapshot(snap => { resources = snap.docs.map(d => ({ id: d.id, ...d.data() })); renderResources(); }, () => renderResources());
    } else { renderSeasons(); renderAbout(); renderHomeStats(); renderDirector(); renderMentors(); renderTeam(); renderContacts(); renderSocials(); renderResources(); }
  } catch (e) { renderSeasons(); renderAbout(); renderHomeStats(); renderDirector(); renderMentors(); renderTeam(); renderContacts(); renderSocials(); renderResources(); }
})();

/* carp fire-breath: follows the pointer, additive particle flames */
(function(){
  const hero=document.getElementById('hero'),cv=document.getElementById('fireCanvas'),carp=document.getElementById('carpDragon');
  if(!hero||!cv||!carp)return;
  const ctx=cv.getContext('2d');let W=0,H=0,dpr=1;
  function size(){dpr=Math.min(devicePixelRatio||1,2);const r=hero.getBoundingClientRect();W=r.width;H=r.height;cv.width=W*dpr;cv.height=H*dpr;}
  size();addEventListener('resize',size);
  const K=[[0,[255,250,225,1]],[.22,[255,205,80,.95]],[.5,[255,115,22,.75]],[.78,[195,42,10,.42]],[1,[70,28,20,0]]];
  function col(t){for(let i=1;i<K.length;i++)if(t<=K[i][0]){const a=K[i-1],b=K[i],u=(t-a[0])/(b[0]-a[0]);return a[1].map((v,j)=>v+(b[1][j]-v)*u);}return K[K.length-1][1];}
  const spr=[];for(let i=0;i<32;i++){const c=col(i/31),g=document.createElement('canvas');g.width=g.height=64;const x=g.getContext('2d'),r=x.createRadialGradient(32,32,0,32,32,32);
    r.addColorStop(0,`rgba(${c[0]|0},${c[1]|0},${c[2]|0},${c[3]})`);r.addColorStop(.45,`rgba(${c[0]|0},${c[1]|0},${c[2]|0},${c[3]*.45})`);r.addColorStop(1,`rgba(${c[0]|0},${c[1]|0},${c[2]|0},0)`);x.fillStyle=r;x.fillRect(0,0,64,64);spr.push(g);}
  let px=0,py=0,last=0,run=false,ps=[],t0=0;
  function mouth(){const r=carp.getBoundingClientRect(),h=hero.getBoundingClientRect();return[r.left-h.left+116/420*r.width,r.top-h.top+134/570*r.height];}
  addEventListener('pointermove',e=>{const h=hero.getBoundingClientRect();if(e.clientX<h.left||e.clientX>h.right||e.clientY<h.top||e.clientY>h.bottom)return;
    px=e.clientX-h.left;py=e.clientY-h.top;last=performance.now();if(!run){run=true;t0=last;requestAnimationFrame(loop);}},{passive:true});
  function emit(mx,my,now){const dx=px-mx,dy=py-my,d=Math.hypot(dx,dy)||1,ang=Math.atan2(dy,dx),sp=Math.max(3.5,Math.min(13,d/42)),n=9;
    for(let i=0;i<n&&ps.length<900;i++){const a=ang+(Math.random()-.5)*.2,v=sp*(.75+Math.random()*.5);
      ps.push({x:mx+Math.cos(ang)*4,y:my+Math.sin(ang)*4+(Math.random()-.5)*5,vx:Math.cos(a)*v,vy:Math.sin(a)*v,l:0,m:38+Math.random()*30,s:8+Math.random()*7,k:Math.random()*6.28});}}
  function loop(now){
    ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,W,H);
    const [mx,my]=mouth(),act=now-last<1800;
    if(act)emit(mx,my,now);
    ctx.globalCompositeOperation='lighter';
    if(act){const g=ctx.createRadialGradient(mx,my,0,mx,my,46);g.addColorStop(0,'rgba(255,190,70,.55)');g.addColorStop(1,'rgba(255,90,10,0)');ctx.fillStyle=g;ctx.fillRect(mx-46,my-46,92,92);}
    for(let i=ps.length-1;i>=0;i--){const p=ps[i];p.l++;if(p.l>=p.m){ps.splice(i,1);continue;}
      const u=p.l/p.m;p.vx=p.vx*.984+Math.sin(now*.006+p.k+p.y*.02)*.16;p.vy=p.vy*.984-.045+Math.cos(now*.005+p.k)*.1;p.x+=p.vx;p.y+=p.vy;
      const sz=(p.s+u*30)*(1-u*.25),sp=spr[Math.min(31,(u*31)|0)];ctx.drawImage(sp,p.x-sz,p.y-sz,sz*2,sz*2);}
    ctx.globalCompositeOperation='source-over';
    if(act||ps.length)requestAnimationFrame(loop);else{run=false;ctx.clearRect(0,0,W,H);}
  }
})();

/* ---- mobile nav toggle ---- */
(function(){
  const nav=document.getElementById('nav'),btn=document.getElementById('navToggle');
  if(!nav||!btn)return;
  const set=o=>{nav.classList.toggle('open',o);btn.setAttribute('aria-expanded',o?'true':'false')};
  btn.addEventListener('click',e=>{e.stopPropagation();set(!nav.classList.contains('open'))});
  nav.querySelectorAll('nav a').forEach(a=>a.addEventListener('click',()=>set(false)));
  document.addEventListener('click',e=>{if(!nav.contains(e.target))set(false)});
  addEventListener('keydown',e=>{if(e.key==='Escape')set(false)});
  addEventListener('hashchange',()=>set(false));
  addEventListener('resize',()=>{if(innerWidth>860)set(false)});
})();
